def revise_lmp_input_model(
    lmp_lines,
    task_model_list,
    trj_freq,
    deepmd_version="1",
    use_ele_temp=0,
    use_clusters=False,
    use_relative=False,
    epsilon=None,
    use_relative_v=False,
    epsilon_v=None,
):
    idx = find_only_one_key(lmp_lines, ["pair_style", "deepmd"])
    graph_list = " ".join(task_model_list)
    if Version(deepmd_version) < Version("1"):
        lmp_lines[idx] = "pair_style      deepmd %s %d model_devi.out\n" % (  # noqa: UP031
            graph_list,
            trj_freq,
        )
    else:
        keywords = ""
        if use_clusters:
            keywords += "atomic "
        if use_relative:
            keywords += "relative %s " % epsilon  # noqa: UP031
        if use_relative_v:
            keywords += "relative_v %s " % epsilon_v  # noqa: UP031
        if use_ele_temp == 1:
            keywords += "fparam ${ELE_TEMP}"
        elif use_ele_temp == 2:
            keywords += "aparam ${ELE_TEMP}"
        keywords = keywords.rstrip()
        if keywords:
            keywords = " " + keywords
        lmp_lines[idx] = (
            "pair_style      deepmd %s out_freq %d out_file model_devi.out%s\n"  # noqa: UP031
            % (
                graph_list,
                trj_freq,
                keywords,
            )
        )
    return lmp_lines


def build_template_options(settings, use_ele_temp=0):
    template_options = dict(settings.get("template_options", {}))
    workflow_options = settings.get("workflow_options", {})
    if not isinstance(workflow_options, dict):
        raise TypeError("workflow_options must be a dictionary")
    if use_ele_temp == 0:
        if settings.get("ele_temp_f") is not None:
            use_ele_temp = 1
        elif settings.get("ele_temp_a") is not None:
            use_ele_temp = 2
    template_options.update(
        {
            "deepmd_version": settings.get("deepmd_version", "1"),
            "use_ele_temp": use_ele_temp,
            "use_clusters": workflow_options.get("use_clusters", False),
            "use_relative": workflow_options.get("use_relative", False),
            "epsilon": workflow_options.get("epsilon"),
            "use_relative_v": workflow_options.get("use_relative_v", False),
            "epsilon_v": workflow_options.get("epsilon_v"),
            "model_devi_merge_traj": workflow_options.get(
                "model_devi_merge_traj", False
            ),
        }
    )
    return template_options


def render_external_template_input(template_lines, task_model_list, trj_freq, template_options):
