#!/usr/bin/env python3
"""Sweep settings combinations through the public workflow and check consistency."""
from __future__ import annotations

import itertools
import sys
from pathlib import Path

task_dir = Path("/workspace/task")
sys.path.insert(0, str(task_dir / "source"))

from dpgen.generator.run import build_template_options, render_external_template_input
from dpgen.generator.lib.lammps import make_lammps_input

failures = []


def compact_lines(lines):
    return [" ".join(raw.split()) for raw in lines]


def check_settings(settings, template_lines, label):
    opts = build_template_options(settings)
    rendered = render_external_template_input(
        list(template_lines), settings["graphs"], settings["trj_freq"], opts
    )
    cl = compact_lines(rendered)

    pair_lines = [l for l in cl if l.startswith("pair_style ") or l == "pair_style"]
    if len(pair_lines) != 1:
        failures.append(f"{label}: expected 1 pair_style line, got {len(pair_lines)}")
        return
    pair = pair_lines[0]

    wo = settings.get("workflow_options", {})
    version = settings.get("deepmd_version", "1")
    from packaging.version import Version

    required = []
    if Version(version) >= Version("1"):
        if wo.get("use_clusters", False):
            required.append("atomic")
        if wo.get("use_relative", False):
            required.append(f"relative {wo['epsilon']}")
        if wo.get("use_relative_v", False):
            required.append(f"relative_v {wo['epsilon_v']}")
        if settings.get("ele_temp_f") is not None:
            required.append("fparam ${ELE_TEMP}")
        elif settings.get("ele_temp_a") is not None:
            required.append("aparam ${ELE_TEMP}")
        required.append(f"out_freq {settings['trj_freq']}")
        required.append("out_file model_devi.out")
    else:
        required.append("model_devi.out")
        required.append(f" {settings['trj_freq']} ")
    for tok in required:
        if tok not in pair:
            failures.append(f"{label}: missing pair token {tok!r} in {pair!r}")

    # graphs must all be present
    for g in settings["graphs"]:
        if g not in pair:
            failures.append(f"{label}: missing graph {g!r} in {pair!r}")

    merge = bool(wo.get("model_devi_merge_traj", False))
    dump_lines = [l for l in cl if l.startswith("dump ") or l == "dump"]
    if not dump_lines:
        failures.append(f"{label}: no dump line")
        return
    dump = dump_lines[0]
    has_modify = any("dump_modify" in l for l in cl)
    if merge:
        if "all.lammpstrj" not in dump:
            failures.append(f"{label}: merge requested, dump={dump!r}")
        if not has_modify:
            failures.append(f"{label}: merge requested, no dump_modify")
    else:
        if "traj/*.lammpstrj" not in dump:
            failures.append(f"{label}: traj dump requested, dump={dump!r}")
        if has_modify:
            failures.append(f"{label}: traj dump requested, stray dump_modify")


base_template = (
    (task_dir / "fixtures" / "public" / "template.lammps").read_text().splitlines(keepends=True)
)

graph_sets = [["graph.000.pb"], ["graph.000.pb", "graph.001.pb", "graph.002.pb"]]
versions = ["1", "0.12"]
trj_freqs = [5, 10, 100]

combo_idx = 0
for graphs, version, trj_freq in itertools.product(graph_sets, versions, trj_freqs):
    for clusters, relative, relative_v, merge in itertools.product(
        [False, True], [False, True], [False, True], [False, True]
    ):
        for ele in [None, ("f", 300.0), ("a", 310.0)]:
            settings = {
                "graphs": graphs,
                "trj_freq": trj_freq,
                "deepmd_version": version,
                "workflow_options": {
                    "use_clusters": clusters,
                    "use_relative": relative,
                    "epsilon": 1.5,
                    "use_relative_v": relative_v,
                    "epsilon_v": 2.0,
                    "model_devi_merge_traj": merge,
                },
            }
            if ele:
                settings[f"ele_temp_{ele[0]}"] = ele[1]
            combo_idx += 1
            label = (
                f"combo{combo_idx}: ng={len(graphs)} v={version} freq={trj_freq} "
                f"c={clusters} r={relative} rv={relative_v} m={merge} ele={ele}"
            )
            check_settings(settings, base_template, label)

            # re-render the rendered output (idempotence / restart replay)
            opts = build_template_options(settings)
            rendered = render_external_template_input(
                base_template, settings["graphs"], settings["trj_freq"], opts
            )
            check_settings(settings, rendered, label + " [replay]")

# also sweep with a make_lammps_input-generated template (its own documented output)
gen_template = make_lammps_input(
    ensemble="nvt",
    conf_file="conf.data",
    graphs=["gA.pb", "gB.pb"],
    nsteps=200,
    dt=0.001,
    neidelay=10,
    trj_freq=20,
    mass_map=[28.0855],
    temp=300.0,
    workflow_options={"model_devi_merge_traj": True},  # dirty: contains dump_modify
    pres=1.0,
    deepmd_version="1",
).splitlines(keepends=True)
assert any("dump_modify" in l for l in gen_template), "expected dirty template"

for merge, clusters in itertools.product([False, True], [False, True]):
    settings = {
        "graphs": ["gA.pb", "gB.pb", "gC.pb"],
        "trj_freq": 7,
        "workflow_options": {
            "use_clusters": clusters,
            "model_devi_merge_traj": merge,
        },
    }
    combo_idx += 1
    check_settings(settings, gen_template, f"combo{combo_idx}: gen-template m={merge} c={clusters}")

# duplicate pair_style template must still raise (ambiguity guard intact)
dup = base_template + ["pair_style      deepmd x.pb out_freq 1 out_file y.out\n"]
try:
    render_external_template_input(
        list(dup), ["x.pb"], 1, build_template_options({"trj_freq": 1})
    )
    failures.append("duplicate pair_style did not raise")
except RuntimeError:
    pass

# template without the dpgen dump key must still raise for dump revision
for tmpl, note in [(gen_template, "gen")]:
    no_dump = [l for l in tmpl.splitlines(keepends=True) if not l.strip().startswith("dump")]
    try:
        render_external_template_input(
            no_dump, ["gA.pb"], 1, build_template_options({"trj_freq": 1})
        )
        failures.append(f"missing dpgen_dump ({note}) did not raise")
    except RuntimeError:
        pass

print(f"swept combos: {combo_idx} (+ replays)")
if failures:
    print(f"FAILURES ({len(failures)}):")
    for f in failures:
        print(" -", f)
    sys.exit(1)
print("all combinations consistent")

